<?php
$id=(int)($_GET['id']??0);if(adjustments_ready()&&(!$id||final_count_is($id))){require __DIR__.'/final_count_page.php';return;}if(!adjustments_ready()||($id&&!adjustment_is_new($id))){require __DIR__.'/inventory_count_legacy_page.php';return;}
function adjustment_form_start($action,$id,$confirm=''){echo '<form method="post" action="inventory_count.php" class="stack"'.($confirm?' data-confirm="'.e($confirm).'"':'').'><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="batch_id" value="'.$id.'">';}
echo '<div class="page-head"><div><h1>Inventory Adjustments</h1><p>Count → Recount → Review → Separate Admin Approval → Posting</p></div><a class="btn ghost" href="?page=reports&report=adjustments">Adjustment Reports</a></div>';
if(!$id){$tab=$_GET['tab']??'count';echo '<div class="tabs">';foreach(['count'=>'Inventory Count','manual'=>'Manual Adjustment','review'=>'Review & Approval','history'=>'Adjustment History'] as $k=>$name)echo '<a class="tab '.($tab===$k?'active':'').'" href="?page=inventory_count&tab='.$k.'">'.$name.'</a>';echo '</div>';
if($tab==='manual'&&can_action('upload_inventory_count'))manual_adjustment_create_form();
if($tab==='count'&&can_action('upload_inventory_count')){echo '<div class="card"><h3>Create Count Session</h3><p>The snapshot is taken now, on the actual count date. Pause movements for counted products until approval. Complete or cancel overlapping count sessions first.</p>';adjustment_form_start('create',0);echo '<div class="report-filter-grid"><label>Count Date<input type="date" name="count_date" value="'.date('Y-m-d').'" min="'.date('Y-m-d').'" max="'.date('Y-m-d').'" required></label><label>Product / SKU Search<input name="q" placeholder="All matching products"></label><label>Brand<select name="brand"><option value="">All Brands</option>';foreach(inventory_brand_options() as $v)echo '<option>'.e($v).'</option>';echo '</select></label><label>Main Category<select name="main_category"><option value="">All Main Categories</option>';foreach(product_category_tree() as $v=>$ss)echo '<option>'.e($v).'</option>';echo '</select></label><label>Subcategory<select name="subcategory"><option value="">All Subcategories</option>';$subs=[];foreach(product_category_tree() as $ss)$subs=array_merge($subs,$ss);foreach(array_unique($subs) as $v)echo '<option>'.e($v).'</option>';echo '</select></label></div><button class="btn primary">Create Count Session</button></form></div>';}
$search=trim($_GET['search']??'');$offset=max(0,(int)($_GET['offset']??0));$where=$tab==='review'?"status IN ('Recount Required','Recounted','Awaiting Approval','Error')":($tab==='history'?"status IN ('Applied','Cancelled','Reversed')":"status NOT IN ('Applied','Cancelled','Reversed')");$q=$pdo->prepare("SELECT * FROM inventory_count_batches WHERE ($where) AND (batch_ref LIKE ? OR created_name LIKE ?) ORDER BY id DESC LIMIT 51 OFFSET $offset");$q->execute(['%'.$search.'%','%'.$search.'%']);$items=$q->fetchAll();echo '<div class="card"><form method="get" class="inline-form"><input type="hidden" name="page" value="inventory_count"><input type="hidden" name="tab" value="'.e($tab).'"><input name="search" value="'.e($search).'" placeholder="Reference / Created by"><button class="btn secondary">Search</button><a class="btn ghost" href="?page=inventory_count&tab='.e($tab).'">Clear Filters</a></form><div class="table-wrap"><table class="table"><tr><th>Reference</th><th>Cutoff</th><th>Status</th><th>Created By</th><th>Reviewer</th><th>Approver</th><th></th></tr>';foreach(array_slice($items,0,50) as $b)echo '<tr><td>'.e($b['batch_ref']).'</td><td>'.e($b['cutoff_at']?:$b['count_date']).'</td><td>'.badge($b['status'],status_badge_class($b['status'])).'</td><td>'.e($b['created_name']).'</td><td>'.e($b['reviewed_name']).'</td><td>'.e($b['approved_name']).'</td><td><a class="btn ghost sm" href="?page=inventory_count&id='.$b['id'].'">View</a></td></tr>';echo '</table></div><div class="modal-actions">';foreach(['Previous'=>max(0,$offset-50),'Next'=>$offset+50] as $label=>$n)if(($label==='Previous'&&$offset)||($label==='Next'&&count($items)>50))echo '<a class="btn ghost" href="?'.e(http_build_query(['page'=>'inventory_count','tab'=>$tab,'search'=>$search,'offset'=>$n])).'">'.$label.'</a>';echo '</div></div>';return;}
try{$b=count_batch($id);$lines=count_lines($id);$closed=in_array($b['status'],['Applied','Cancelled','Reversed'],true);$errors=json_decode($b['error_json']??'[]',true)?:[];$stale=[];if(!$closed)foreach($lines as $l)if(!hash_equals($l['stock_signature'],count_stock_signature($l['product_id'])))$stale[]=$l['master_sku'];
echo '<div class="card"><div class="card-head"><h3>'.e($b['batch_ref']).' · Record #'.$id.'</h3>'.badge($b['status'],status_badge_class($b['status'])).'</div><p>Cutoff: '.e($b['cutoff_at']).' · Count Date: '.e($b['count_date']).' · Revision '.$b['revision'].'</p><p>Created by '.e($b['created_name']).' · Reviewer: '.e($b['reviewed_name']?:'Pending').' · Approver: '.e($b['approved_name']?:'Pending').'</p><div class="modal-actions"><a class="btn ghost" href="?page=inventory_count">All Count Sessions</a><a class="btn ghost" href="inventory_count.php?id='.$id.'&results=1">Download Results Excel</a><a class="btn ghost" target="_blank" rel="noopener" href="inventory_count.php?id='.$id.'&results=1&format=print">Print Results / PDF</a></div></div>';
adjustment_record_notification($b);
if($stale)echo '<div class="alert danger"><b>Stock changed after cutoff:</b> '.e(implode(', ',$stale)).'. Approval blocked. Cancel and create a fresh count snapshot.</div>';if($errors){echo '<div class="alert danger"><b>Upload Errors</b><ul>';foreach($errors as $err)echo '<li>'.e($err).'</li>';echo '</ul></div>';}
manual_adjustment_entry_forms($b,$lines);
if(!$closed&&$b['status']!=='Awaiting Approval'&&can_action('upload_inventory_count')){echo '<div class="card"><h3>Count & Recount Sheets</h3><p>Fill all four conditions for counted rows. Blank is not counted; 0 means zero. Recount every counted product. Brands/categories are filters only, excluded from count sheets.</p><div class="modal-actions"><a class="btn secondary" href="inventory_count.php?id='.$id.'&download=1">Download First Count Sheet</a><a class="btn secondary" href="inventory_count.php?id='.$id.'&download=1&stage=Recount">Download Recount Sheet</a><a class="btn ghost" target="_blank" rel="noopener" href="inventory_count.php?id='.$id.'&print=1">Print Count Sheet / PDF</a></div><form method="post" action="inventory_count.php" enctype="multipart/form-data" class="inline-form"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="upload"><input type="hidden" name="batch_id" value="'.$id.'"><input type="file" name="file" accept=".xlsx" required><button class="btn primary">Upload & Validate</button></form></div>';}
echo '<div class="card table-wrap"><h3>Count Validation</h3><table class="table"><tr><th>SKU / Product</th><th>Snapshot Good / Packaging / Damaged / Other</th><th>Physical On Hand</th><th>First Count</th><th>Recount</th><th>Final Verified</th><th>Physical Variance</th><th>Remarks</th></tr>';foreach($lines as $l){$snap=json_decode($l['snapshot_conditions'],true);$first=json_decode($l['remarks']??'null',true);$rc=json_decode($l['recount_json']??'null',true);$final=json_decode($l['final_conditions']??'null',true);$fmt=fn($v)=>is_array($v)?implode(' / ',array_values($v)):'—';echo '<tr><td>'.e($l['master_sku']).'<br>'.e($l['product_name']).'</td><td>'.e($fmt($snap)).'</td><td>'.$l['on_hand'].'</td><td>'.e($fmt($first['first']??null)).'</td><td>'.e($fmt($rc['counts']??null)).'</td><td>'.e($fmt($final)).'</td><td>'.($rc?array_sum($rc['counts'])-(int)$l['on_hand']:'—').'</td><td>'.e(($first['first_remarks']??'').' | '.($rc['remarks']??'')).'</td></tr>';}echo '</table></div>';
if(in_array($b['status'],['Recounted','Awaiting Approval','Applied','Reversed'],true)){$a=$closed?null:adjustment_plan($id);echo '<div class="card"><h3>Final Adjustment & Platform Allocation</h3><p>Use these approved quantities to set stocks in actual marketplaces immediately after approval. Marketplace updates are manual.</p><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Physical Variance</th><th>Sellable Before → After</th><th>Lazada Final</th><th>Shopee Final</th><th>TikTok Final</th></tr>';$plans=$a?$a['lines']:array_filter(array_map(fn($l)=>json_decode($l['posting_json']??'null',true),$lines));foreach($plans as $l){echo '<tr><td>'.e($l['product']).'</td><td>'.$l['physical_delta'].'</td><td>'.$l['snapshot']['good'].' → '.$l['recount']['good'].'</td>';foreach(['Lazada','Shopee','TikTok'] as $pl)echo '<td>'.$l['final_platforms'][$pl].'</td>';echo '</tr>';}echo '</table></div>';
if($b['status']==='Recounted'&&can_action('upload_inventory_count')){adjustment_form_start('review',$id,'Submit verified recount for separate Admin approval? No stock changes yet.');echo '<input type="hidden" name="revision" value="'.$b['revision'].'"><label>Required Adjustment Reason<textarea name="reason" minlength="3" required>'.e($b['reason']).'</textarea></label><label>Supporting Reference<input name="support_reference" value="'.e($b['support_reference']).'" placeholder="Signed count sheet / investigation reference" minlength="3" maxlength="255" required></label><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I verified the recount, discrepancies and allocation.</label><button class="btn primary" '.($stale?'disabled':'').'>Submit Review for Approval</button></form>';}
if($b['status']==='Awaiting Approval'){echo '<p>Reason: '.e($b['reason']).'<br>Supporting Reference: '.e($b['support_reference']).'</p>';if(current_user()['role']==='Admin'&&(int)$b['reviewed_by']!==current_user()['id']){adjustment_form_start('post',$id,'Approve physical adjustment and 20/40/40 redistribution? Stocks will change.');echo '<input type="hidden" name="digest" value="'.e($a['digest']).'"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I approve the final counts, reasons and allocation.</label><button class="btn primary" '.($stale?'disabled':'').'>Approve & Post Adjustment</button></form>';}else echo '<div class="alert warn">A different Admin must approve. Reviewers cannot approve their own review.</div>';if(can_action('upload_inventory_count')){adjustment_form_start('return_review',$id);echo '<label>Reason to Return for Review<input name="reason" minlength="3" required></label><button class="btn ghost">Return for Review</button></form>';}}echo '</div>';}
if(!$closed&&can_action('upload_inventory_count')){echo '<div class="card">';adjustment_form_start('cancel',$id,'Cancel this count session? No stock changes.');echo '<label>Cancellation Reason<input name="reason" minlength="3" required></label><button class="btn danger">Cancel Count Session</button></form></div>';}
if($b['status']==='Applied'&&can_action('reversal_request'))echo '<div class="card"><h3>Correct a Posted Mistake</h3><form method="post" action="actions.php" class="inline-form"><input type="hidden" name="action" value="reversal_request"><input type="hidden" name="return" value="corrections"><input type="hidden" name="source_type" value="Inventory Count"><input type="hidden" name="source_id" value="'.$id.'"><input name="reason" placeholder="Required correction reason" minlength="3" required><button class="btn secondary">Request Linked Reversal</button></form></div>';
echo '<div class="card table-wrap"><h3>Physical Adjustment & Redistribution History</h3><table class="table"><tr><th>Movement</th><th>Product</th><th>Physical Change</th><th>Sellable Change</th><th>Platform Changes</th><th>Recorded At</th></tr>';$q=db()->prepare('SELECT m.*,p.name FROM adjustment_movements m JOIN products p ON p.id=m.product_id WHERE batch_id=? ORDER BY m.id');$q->execute([$id]);foreach($q as $m)echo '<tr><td>'.e($m['movement_type']).'</td><td>'.e($m['name']).'</td><td>'.$m['physical_delta'].'</td><td>'.$m['sellable_delta'].'</td><td>'.e($m['platform_json']).'</td><td>'.e($m['created_at']).'</td></tr>';echo '</table><h3>Review & Approval Trail</h3><table class="table"><tr><th>When</th><th>Event</th><th>Revision</th><th>User</th><th>Details</th></tr>';$q=db()->prepare('SELECT v.*,u.name FROM count_review_events v LEFT JOIN users u ON u.id=v.user_id WHERE batch_id=? ORDER BY v.id');$q->execute([$id]);foreach($q as $v)echo '<tr><td>'.e($v['created_at']).'</td><td>'.e($v['event_type']).'</td><td>'.$v['revision'].'</td><td>'.e($v['name']).'</td><td>'.e($v['details_json']).'</td></tr>';echo '</table><h3>Uploaded Evidence</h3><table class="table"><tr><th>When</th><th>Filename / Stage</th><th>Revision</th><th>Errors</th><th>File</th></tr>';$q=db()->prepare('SELECT * FROM count_upload_evidence WHERE batch_id=? ORDER BY id');$q->execute([$id]);foreach($q as $v)echo '<tr><td>'.e($v['created_at']).'</td><td>'.e($v['filename'].' / '.$v['stage']).'</td><td>'.$v['revision'].'</td><td>'.e($v['errors_json']).'</td><td>'.($v['stored_path']?'<a class="btn ghost sm" href="inventory_count.php?id='.$id.'&evidence='.$v['id'].'">Download</a>':'Validation record').'</td></tr>';echo '</table></div>';
}catch(Throwable $ex){echo '<div class="alert danger">'.e(safe_error_message($ex)).'</div>';}
